const body = $input.first().json.body;
const idToken = (body.id_token || '').trim();
const areaFrontend = (body.area || '').replace(/^Acceso a\s*/i, '').trim();
if (!idToken) return [{ json: { tokenValido: false, error: 'No se recibió id_token. Inicia sesión con Microsoft.', areaFrontend } }];
const parts = idToken.split('.');
if (parts.length !== 3) return [{ json: { tokenValido: false, error: 'Token malformado (no es un JWT válido).', areaFrontend } }];
let header, payload;
try { header = JSON.parse(Buffer.from(parts[0], 'base64url').toString('utf8')); payload = JSON.parse(Buffer.from(parts[1], 'base64url').toString('utf8')); } catch(e) { return [{ json: { tokenValido: false, error: 'Error al decodificar token: ' + e.message, areaFrontend } }]; }
const CLIENT_ID = 'TU_CLIENT_ID_AZURE';
const TENANT_ID = 'TU_TENANT_ID_AZURE';
const ahora = Math.floor(Date.now() / 1000);
if (payload.exp && payload.exp < ahora) return [{ json: { tokenValido: false, error: 'Token expirado. Vuelve a iniciar sesión.', areaFrontend } }];
if (payload.nbf && payload.nbf > ahora + 300) return [{ json: { tokenValido: false, error: 'Token aún no válido (nbf).', areaFrontend } }];
const audiences = Array.isArray(payload.aud) ? payload.aud : [payload.aud];
if (!audiences.includes(CLIENT_ID)) return [{ json: { tokenValido: false, error: 'Audience inválido: ' + JSON.stringify(payload.aud), areaFrontend } }];
const validIssuers = [`https://login.microsoftonline.com/${TENANT_ID}/v2.0`, `https://sts.windows.net/${TENANT_ID}/`];
if (!validIssuers.includes(payload.iss)) return [{ json: { tokenValido: false, error: 'Issuer inválido: ' + payload.iss, areaFrontend } }];
const email = payload.email || payload.preferred_username || payload.upn || '';
const nombre = payload.name || payload.given_name || '';
const cargo = payload.jobTitle || '';
const departamento = payload.department || '';
if (!departamento) return [{ json: { tokenValido: false, error: 'El token no contiene el claim department. Habilítalo en Azure → Token configuration.', areaFrontend, email, nombre } }];
return [{ json: { tokenValido: true, email, nombre, cargo, departamento, accountEnabled: true, areaFrontend, tokenAlg: header.alg, tokenExp: new Date(payload.exp * 1000).toISOString() } }];

const user = $input.first().json;
const deptRaw = (user.departamento || '').trim().toLowerCase();
const areaFrontend = user.areaFrontend || '';
const deptMap = { 'soporte': 'Soporte', 'marketing': 'Marketing', 'contabilidad': 'Contabilidad', 'comercial': 'Comercial', 'sales operations': 'Comercial', 'sales operatins': 'Comercial', 'sales operations ': 'Comercial', 'sales operations management': 'Comercial', 'operaciones': 'Operaciones', 'calidad': 'Calidad', 'ti': 'TI', 'desarrollo': 'TI', 'gerencia': 'Gerencia', 'd. organizacional': 'Gerencia', 'analítica de datos': 'Analítica', 'analitica de datos': 'Analítica', 'co': 'Comercial' };
const areaMapeada = deptMap[deptRaw] || null;
const tieneAcceso = areaMapeada === areaFrontend;
return [{ json: { email: user.email, nombre: user.nombre, cargo: user.cargo, departamento: user.departamento, areaMapeada, areaFrontend, tieneAcceso, accountEnabled: user.accountEnabled } }];

const redirects = { 'Soporte': 'https://soporte.mobilvendor.com', 'Marketing': 'https://marketing.mobilvendor.com', 'Contabilidad': 'https://contabilidad.mobilvendor.com', 'Comercial': 'https://comercial.mobilvendor.com', 'Operaciones': 'https://operaciones.mobilvendor.com', 'Calidad': 'https://calidad.mobilvendor.com', 'TI': 'https://ti.mobilvendor.com', 'Gerencia': 'https://gerencia.mobilvendor.com', 'Analitica': 'https://analitica.mobilvendor.com' };
const area = $json.areaMapeada;
const url = redirects[area] || 'https://intranet.mobilvendor.com';
const sessionPayload = { email: $json.email, nombre: $json.nombre, cargo: $json.cargo, area: area, iat: Date.now(), exp: Date.now() + (8 * 60 * 60 * 1000) };
const sessionToken = Buffer.from(JSON.stringify(sessionPayload)).toString('base64url');
return [{ json: { status: 'ok', redirect: url, nombre: $json.nombre, cargo: $json.cargo, email: $json.email, area: area, sessionToken } }];

